<!doctype html><html lang="ro"><head><meta charset="utf-8"><style>@page{margin:22px}body{font-family:DejaVu Sans,sans-serif;color:#172033;font-size:9px}.page{page-break-after:always}.page:last-child{page-break-after:auto}h1{font-size:17px;text-align:center;margin:0 0 5px}.subtitle{text-align:center;margin:0 0 18px;color:#526070}table{width:100%;border-collapse:collapse;margin-top:12px}th{background:#e8eef8}th,td{border:1px solid #aebdce;padding:5px;vertical-align:top}.right{text-align:right}.meta td{border:0;padding:3px;width:25%}.footer{margin-top:28px}.signature{display:inline-block;width:31%;text-align:center;margin-right:2%;padding-top:32px;border-top:1px solid #64748b}</style></head><body>@foreach($receptions as $reception)<section class="page"><h1>NOTĂ DE RECEPȚIE ȘI INTRARE ÎN GESTIUNE</h1><p class="subtitle">{{ $reception->number }} · Data recepției: {{ optional($reception->received_at)->format('d.m.Y') }}</p><table class="meta"><tr><td><b>Furnizor:</b><br>{{ $reception->supplier?->name ?? '—' }}</td><td><b>Gestiune:</b><br>{{ $reception->warehouse?->name ?? '—' }}</td><td><b>Document furnizor:</b><br>{{ trim(($reception->invoice_series ?? '').' '.($reception->invoice_number ?? $reception->supplier_document_number ?? '—')) }}</td><td><b>Delegat / auto:</b><br>{{ $reception->delegate ?: '—' }} {{ $reception->vehicle ? ' / '.$reception->vehicle : '' }}</td></tr></table><table><thead><tr><th>Nr.</th><th>Denumire produs</th><th>Cod</th><th>U.M.</th><th>Cantitate</th><th>Preț unitar</th><th>TVA</th><th>Valoare</th></tr></thead><tbody>@foreach($reception->items as $index => $item)<tr><td>{{ $index + 1 }}</td><td>{{ $item->product_name ?: $item->product?->name }}</td><td>{{ $item->product_code ?: '—' }}</td><td>{{ $item->unit }}</td><td class="right">{{ number_format((float) $item->quantity, 3, ',', '.') }}</td><td class="right">{{ number_format((float) $item->unit_price, 2, ',', '.') }}</td><td class="right">{{ number_format((float) $item->vat_rate, 0) }}%</td><td class="right">{{ number_format((float) $item->line_total, 2, ',', '.') }}</td></tr>@endforeach</tbody></table><p class="right"><b>Total recepție: {{ number_format((float) $reception->total, 2, ',', '.') }} {{ $reception->currency ?: 'RON' }}</b></p>@if($reception->mentions || $reception->difference_notes)<p><b>Mențiuni:</b> {{ $reception->mentions ?: $reception->difference_notes }}</p>@endif<p class="footer"><span class="signature">Comisia de recepție</span><span class="signature">Gestionar</span><span class="signature">Predător / delegat</span></p></section>@endforeach</body></html>
